CREATE OR REPLACE FUNCTION public.is_admin_or_master(p_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_user_id IS NOT NULL AND (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user_id AND role::text IN ('master','senior')) OR (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user_id AND role::text='admin') AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=p_user_id AND role::text='financeiro'))) $$;
CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid,_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _permission IN ('users.update','users.reset','users.promote','users.demote','roles.manage','admins.invite','admins.remove') THEN public.is_master(_user_id) WHEN _permission IN ('finance.read') THEN public.can_read_finance(_user_id) WHEN _permission IN ('finance.settle','finance.release') THEN public.can_write_finance(_user_id) WHEN _permission='ads.manage' THEN public.is_admin_or_master(_user_id) OR public.can_write_finance(_user_id) WHEN _permission='settings.manage' THEN EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text IN ('senior','master')) WHEN _permission IN ('users.read','reports.read','audit_logs.read') THEN public.is_admin_or_master(_user_id) WHEN _permission IN ('submit','approve','edit','delete','events.create','events.read','events.update','events.approve','events.cancel','events.delete') THEN public.is_admin_or_master(_user_id) OR (NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text='financeiro') AND EXISTS(SELECT 1 FROM public.collaborators c WHERE c.user_id=_user_id AND c.is_active AND ((_permission IN ('submit','events.create') AND c.can_submit) OR (_permission IN ('approve','events.approve') AND c.can_approve) OR (_permission IN ('edit','events.update') AND c.can_edit) OR (_permission IN ('delete','events.delete') AND c.can_delete) OR _permission='events.read'))) ELSE false END $$;
CREATE OR REPLACE FUNCTION public.can_create_events(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id IS NOT NULL AND (public.is_admin_or_master(_user_id) OR (NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text='financeiro') AND (EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_user_id AND lower(coalesce(user_type,'')) IN ('divulgador','promotor')) OR EXISTS(SELECT 1 FROM public.collaborators WHERE user_id=_user_id AND is_active AND can_submit)))) $$;
CREATE OR REPLACE FUNCTION public.is_promotor(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.can_create_events(_user_id) $$;
CREATE OR REPLACE FUNCTION public.prevent_role_self_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.role IS DISTINCT FROM OLD.role THEN RAISE EXCEPTION 'Papéis administrativos são definidos somente em user_roles'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.prevent_user_type_self_escalation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.user_type IS DISTINCT FROM OLD.user_type AND auth.role() IS DISTINCT FROM 'service_role' AND NOT public.is_master(auth.uid()) THEN RAISE EXCEPTION 'Somente Master pode alterar o tipo de perfil'; END IF; RETURN NEW; END $$;
CREATE POLICY profiles_master_update ON public.profiles FOR UPDATE TO authenticated USING(public.is_master(auth.uid())) WITH CHECK(public.is_master(auth.uid()));
ALTER POLICY "Admins and masters can insert collaborators" ON public.collaborators WITH CHECK(public.is_master(auth.uid()));
ALTER POLICY "Admins and masters can update collaborators" ON public.collaborators USING(public.is_master(auth.uid())) WITH CHECK(public.is_master(auth.uid()));
ALTER POLICY "Admins and masters can delete collaborators" ON public.collaborators USING(public.is_master(auth.uid()));
ALTER POLICY admin_update ON public.divulgador_requests USING(public.is_master(auth.uid())) WITH CHECK(public.is_master(auth.uid()));
CREATE POLICY ads_finance_read ON public.ads FOR SELECT TO authenticated USING(public.can_write_finance(auth.uid()));
CREATE POLICY ads_finance_insert ON public.ads FOR INSERT TO authenticated WITH CHECK(public.can_write_finance(auth.uid()) AND user_id=auth.uid());
CREATE POLICY ads_finance_update ON public.ads FOR UPDATE TO authenticated USING(public.can_write_finance(auth.uid())) WITH CHECK(public.can_write_finance(auth.uid()));
CREATE POLICY ads_finance_delete ON public.ads FOR DELETE TO authenticated USING(public.can_write_finance(auth.uid()));
CREATE POLICY ad_plans_finance_manage ON public.ad_plans FOR ALL TO authenticated USING(public.can_write_finance(auth.uid())) WITH CHECK(public.can_write_finance(auth.uid()));
ALTER POLICY "Admins can moderate any media" ON public.artist_media USING(public.is_admin_or_master(auth.uid())) WITH CHECK(public.is_admin_or_master(auth.uid()));
ALTER POLICY "Admins can delete any media" ON public.artist_media USING(public.is_admin_or_master(auth.uid()));
ALTER POLICY app_settings_admin_insert ON public.app_settings WITH CHECK(public.has_permission(auth.uid(),'settings.manage'));
ALTER POLICY app_settings_admin_update ON public.app_settings USING(public.has_permission(auth.uid(),'settings.manage')) WITH CHECK(public.has_permission(auth.uid(),'settings.manage'));
ALTER POLICY app_settings_admin_delete ON public.app_settings USING(public.has_permission(auth.uid(),'settings.manage'));
GRANT EXECUTE ON FUNCTION public.is_admin_or_master(uuid),public.has_permission(uuid,text),public.can_create_events(uuid),public.is_promotor(uuid) TO authenticated,service_role;